PROGRAM intersection
VAR_OUTPUT
NS_G : BOOL;
NS_Y : BOOL;
NS_R : BOOL;
EW_G : BOOL;
EW_Y : BOOL;
EW_R : BOOL;
END_VAR
VAR
State : INT := 0;
GreenTimer : TON;
YellowTimer : TON;
AllRedTimer : TON;
END_VAR
VAR CONSTANT
PT_GREEN : TIME := T#2s;
PT_YELLOW : TIME := T#1s;
PT_ALLRED : TIME := T#1s;
END_VAR
GreenTimer(IN := (State = 0) OR (State = 3), PT := PT_GREEN);
YellowTimer(IN := (State = 1) OR (State = 4), PT := PT_YELLOW);
AllRedTimer(IN := (State = 2) OR (State = 5), PT := PT_ALLRED);
IF GreenTimer.Q THEN
IF State = 0 THEN State := 1;
ELSIF State = 3 THEN State := 4;
END_IF;
ELSIF YellowTimer.Q THEN
IF State = 1 THEN State := 2;
ELSIF State = 4 THEN State := 5;
END_IF;
ELSIF AllRedTimer.Q THEN
IF State = 2 THEN State := 3;
ELSIF State = 5 THEN State := 0;
END_IF;
END_IF;
CASE State OF
0:
NS_G := TRUE; NS_Y := FALSE; NS_R := FALSE;
EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
1:
NS_G := FALSE; NS_Y := TRUE; NS_R := FALSE;
EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
2:
NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
3:
NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
EW_G := TRUE; EW_Y := FALSE; EW_R := FALSE;
4:
NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
EW_G := FALSE; EW_Y := TRUE; EW_R := FALSE;
5:
NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
ELSE
State := 0;
END_CASE;
END_PROGRAM

PROGRAM intersection
VAR_OUTPUT
  NS_G : BOOL;
  NS_Y : BOOL;
  NS_R : BOOL;
  EW_G : BOOL;
  EW_Y : BOOL;
  EW_R : BOOL;
END_VAR
VAR
  State : INT := 0;
  green_timer : TON;
  yellow_timer : TON;
  allred_timer : TON;
END_VAR
VAR CONSTANT
  PT_GREEN : TIME := T#2s;
  PT_YELLOW : TIME := T#1s;
  PT_ALLRED : TIME := T#1s;
END_VAR

CASE State OF
  0: (* NS green / EW red *)
    NS_G := TRUE; NS_Y := FALSE; NS_R := FALSE;
    EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
    green_timer(IN := TRUE, PT := PT_GREEN);
    yellow_timer(IN := FALSE, PT := PT_YELLOW);
    allred_timer(IN := FALSE, PT := PT_ALLRED);
    IF green_timer.Q THEN
      State := 1;
      green_timer(IN := FALSE, PT := PT_GREEN);
    END_IF;
  1: (* NS yellow / EW red *)
    NS_G := FALSE; NS_Y := TRUE; NS_R := FALSE;
    EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
    green_timer(IN := FALSE, PT := PT_GREEN);
    yellow_timer(IN := TRUE, PT := PT_YELLOW);
    allred_timer(IN := FALSE, PT := PT_ALLRED);
    IF yellow_timer.Q THEN
      State := 2;
      yellow_timer(IN := FALSE, PT := PT_YELLOW);
    END_IF;
  2: (* all-red clearance *)
    NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
    EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
    green_timer(IN := FALSE, PT := PT_GREEN);
    yellow_timer(IN := FALSE, PT := PT_YELLOW);
    allred_timer(IN := TRUE, PT := PT_ALLRED);
    IF allred_timer.Q THEN
      State := 3;
      allred_timer(IN := FALSE, PT := PT_ALLRED);
    END_IF;
  3: (* EW green / NS red *)
    NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
    EW_G := TRUE; EW_Y := FALSE; EW_R := FALSE;
    green_timer(IN := TRUE, PT := PT_GREEN);
    yellow_timer(IN := FALSE, PT := PT_YELLOW);
    allred_timer(IN := FALSE, PT := PT_ALLRED);
    IF green_timer.Q THEN
      State := 4;
      green_timer(IN := FALSE, PT := PT_GREEN);
    END_IF;
  4: (* EW yellow / NS red *)
    NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
    EW_G := FALSE; EW_Y := TRUE; EW_R := FALSE;
    green_timer(IN := FALSE, PT := PT_GREEN);
    yellow_timer(IN := TRUE, PT := PT_YELLOW);
    allred_timer(IN := FALSE, PT := PT_ALLRED);
    IF yellow_timer.Q THEN
      State := 5;
      yellow_timer(IN := FALSE, PT := PT_YELLOW);
    END_IF;
  5: (* all-red clearance *)
    NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
    EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
    green_timer(IN := FALSE, PT := PT_GREEN);
    yellow_timer(IN := FALSE, PT := PT_YELLOW);
    allred_timer(IN := TRUE, PT := PT_ALLRED);
    IF allred_timer.Q THEN
      State := 0;
      allred_timer(IN := FALSE, PT := PT_ALLRED);
    END_IF;
ELSE
  State := 0;
END_CASE;
END_PROGRAM

