    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR
    State : INT := 0;
    ReactTimer : TON;
END_VAR
VAR CONSTANT
    LVL_HIGH : INT := 80;
    TEMP_SET : INT := 100;
    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
END_VAR
IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
    ReactTimer(IN := FALSE, PT := T#3s);
    RETURN;
END_IF;
CASE State OF
    0: (* Idle *)
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
        ReactTimer(IN := FALSE, PT := T#3s);
        IF StartBatch THEN
            State := 1;
        END_IF;
    1: (* Fill *)
        FillValve := TRUE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
        ReactTimer(IN := FALSE, PT := T#3s);
        IF Level >= LVL_HIGH THEN
            State := 2;
        END_IF;
    2: (* Heat *)
        FillValve := FALSE;
        Heater := (Level >= LIQ_MIN);
        Agitator := (Level >= LIQ_MIN);
        DrainValve := FALSE;
        ReactTimer(IN := FALSE, PT := T#3s);
        IF Temp >= TEMP_SET THEN
            State := 3;
        END_IF;
    3: (* React *)
        FillValve := FALSE;
        Heater := (Level >= LIQ_MIN);
        Agitator := (Level >= LIQ_MIN);
        DrainValve := FALSE;
        ReactTimer(IN := TRUE, PT := T#3s);
        IF ReactTimer.Q THEN
            State := 4;
        END_IF;
    4: (* Drain *)
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := TRUE;
        ReactTimer(IN := FALSE, PT := T#3s);
        IF Level <= LVL_LOW THEN
            State := 0;
        END_IF;
ELSE
    State := 0;
END_CASE;
IF (FillValve AND DrainValve) THEN
    FillValve := FALSE;
    DrainValve := FALSE;
END_IF;
IF (Heater OR Agitator) AND (Level < LIQ_MIN) THEN
    Heater := FALSE;
    Agitator := FALSE;
END_IF;
END_PROGRAM

