        IF ReactTimer.Q THEN
            ReactTimer(IN := FALSE, PT := REACT_PT);
            State := 4;
        END_IF;

    4: (* Drain *)
        DrainValve := TRUE;
        IF Level <= LVL_LOW THEN
            State := 0;
        END_IF;
