    IF StartPB AND Healthy THEN
      State := 1;
    END_IF;
  1:
    IF NOT Healthy THEN
      State := 0;
    ELSIF PurgeTimer.Q THEN
      State := 2;
    END_IF;
    Fan := TRUE;
    Fuel := FALSE;
    Ignition := FALSE;
    PurgeTimer(IN := TRUE, PT := T#3s);
    IgnTimer(IN := FALSE, PT := T#2s);
  2:
