    ELSIF IgnTimer.Q THEN
      IF Flame THEN
        State := 3;
      ELSE
        State := 0;
      END_IF;
    END_IF;
    Fan := TRUE;
    Fuel := TRUE;
    Ignition := TRUE;
    PurgeTimer(IN := FALSE, PT := T#3s);
    IgnTimer(IN := TRUE, PT := T#2s);
  3:
    IF NOT Healthy OR NOT Flame THEN
      State := 0;
    END_IF;
    Fan := TRUE;
    Fuel := TRUE;
    Ignition := FALSE;
