PROGRAM burner
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
    Flame : BOOL;
END_VAR
VAR_OUTPUT
    Fan : BOOL;
    Fuel : BOOL;
    Ignition : BOOL;
END_VAR
VAR
    State : INT;
    PurgeTimer : TON;
    IgnTimer : TON;
END_VAR
CASE State OF
    0: (* Off *)
        Fan := FALSE;
        Fuel := FALSE;
        Ignition := FALSE;
        PurgeTimer(IN := FALSE, PT := T#3s);
        IgnTimer(IN := FALSE, PT := T#2s);
        IF StartPB AND EStop AND NOT StopPB THEN
            State := 1;
            PurgeTimer(IN := TRUE, PT := T#3s);
        END_IF;
    1: (* Pre-purge *)
        Fan := TRUE;
        Fuel := FALSE;
        Ignition := FALSE;
        PurgeTimer(IN := TRUE, PT := T#3s);
        IF NOT EStop OR StopPB THEN
            State := 0;
        ELSIF PurgeTimer.Q THEN
            State := 2;
            PurgeTimer(IN := FALSE, PT := T#3s);
            IgnTimer(IN := TRUE, PT := T#2s);
        END_IF;
    2: (* Ignition trial *)
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := TRUE;
        IgnTimer(IN := TRUE, PT := T#2s);
        IF NOT EStop OR StopPB THEN
            State := 0;
        ELSIF IgnTimer.Q THEN
            IgnTimer(IN := FALSE, PT := T#2s);
            IF Flame THEN
                State := 3;
            ELSE
                State := 0;
            END_IF;
        END_IF;
    3: (* Run *)
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;
        IF NOT EStop OR StopPB OR NOT Flame THEN
            State := 0;
        END_IF;
ELSE
    State := 0;
END_CASE;
END_PROGRAM

